timeseries r = sum(custom.nexus.log.adapter.responses), by: { cluster, service }
| filter (in("*", $Cluster) or in(cluster, $Cluster)) and isNotNull(service)
| summarize n = count(), by: { service }
| fields service = service
| append [data record(service = "*")]
| sort service asc

