| filter (in("*", $Cluster) or in(cluster, $Cluster))
| fieldsKeep timeframe, interval, component, avg_ms

31.query:
timeseries c = sum(custom.nexus.log.adapter.backend_calls), by: { cluster, component, latency_bucket }
| filter (in("*", $Cluster) or in(cluster, $Cluster))
| fieldsAdd n = arraySum(c)
| summarize calls = sum(n),
    slow_1s = sum(if(in(latency_bucket, array("1-5s", "5s+")), n, else: 0)),
    slow_5s = sum(if(latency_bucket == "5s+", n, else: 0)), by: { component }
| fieldsAdd pct_over_1s = round(100.0 * slow_1s / calls, decimals: 2),
            pct_over_5s = round(100.0 * slow_5s / calls, decimals: 2)
| lookup [
    timeseries m = max(custom.nexus.log.adapter.backend_ms), by: { component }
    | fieldsAdd max_ms = arrayMax(m)
  ], sourceField: component, lookupField: component, fields: { max_ms }
| sort pct_over_1s desc

